/**
 * Traducciones de los mensajes que el servidor devuelve en `error` / `message`.
 *
 * La clave es el texto canónico en español tal como aparece en el código; el valor,
 * sus traducciones en el orden [en, pt, fr, it]. `localizeJsonResponses` (en
 * `serverI18n.ts`) las aplica a toda respuesta JSON según el idioma de la petición,
 * así que los handlers siguen escribiendo el mensaje en español.
 *
 * Los correos no pasan por aquí. Para un mensaje nuevo: añadirlo a este mapa
 * (el test `tests/server-i18n.test.ts` comprueba que las cuatro traducciones existan).
 */
export type ResponseTranslation = readonly [en: string, pt: string, fr: string, it: string];

