/** Mensajes con datos variables: patrón sobre el texto en español y traducciones [en, pt, fr, it]. */
export const RESPONSE_PATTERNS: Array<{ pattern: RegExp; translate: (m: RegExpMatchArray) => ResponseTranslation }> = [
  {
    pattern: /^Usuario no encontrado: (.+)$/s,
    translate: (m) => [`User not found: ${m[1]}`, `Usuário não encontrado: ${m[1]}`, `Utilisateur introuvable : ${m[1]}`, `Utente non trovato: ${m[1]}`],
  },
  {
    pattern: /^Esta carpeta de Drive ya se importó como "(.*)"\.$/s,
    translate: (m) => [
      `This Drive folder was already imported as "${m[1]}".`,
      `Esta pasta do Drive já foi importada como "${m[1]}".`,
      `Ce dossier Drive a déjà été importé sous le nom « ${m[1]} ».`,
      `Questa cartella di Drive è già stata importata come "${m[1]}".`,
    ],
  },
  {
    pattern: /^Acceso al curso «(.*)» aprobado para (.*)\.$/s,
    translate: (m) => [
      `Access to the course "${m[1]}" approved for ${m[2]}.`,
      `Acesso ao curso "${m[1]}" aprovado para ${m[2]}.`,
      `Accès au cours « ${m[1]} » approuvé pour ${m[2]}.`,
      `Accesso al corso "${m[1]}" approvato per ${m[2]}.`,
    ],
  },
  {
    pattern: /^La opinión no puede pasar de (\d+) caracteres$/,
    translate: (m) => [
      `The review can't exceed ${m[1]} characters`,
      `A opinião não pode passar de ${m[1]} caracteres`,
      `L'avis ne peut pas dépasser ${m[1]} caractères`,
      `L'opinione non può superare ${m[1]} caratteri`,
    ],
  },
];
